import { IBackpack } from '@apps/Hiking/@types/equip.types';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohImagePlaceholder from '@ui-kit/ImagePlaceholder';

interface IBackpackVerticalProps extends React.HTMLAttributes<HTMLDivElement> {
  backpack: IBackpack;
}

const BackpackVertical: React.FC<IBackpackVerticalProps> = ({
  backpack,
  children,
  ...rest
}: IBackpackVerticalProps) => {
  return (
    <div {...rest}>
      <small className="text-muted">Рюкзак</small>
      <h3 className="mt-0">{backpack.name}</h3>
      <p>
        Вес рюкзака: <strong>{backpack.weight} кг.</strong>
        <br />
        Объем рюкзака: <strong>{backpack.value} л.</strong>
      </p>
      <div className="position-relative">
        {children}
        <PohImagePlaceholder
          src={backpack.photo}
          style={{ width: '100%' }}
          alt={backpack.name}
          iconName={IconsEnum.backpack}
        />
      </div>
    </div>
  );
};

export default BackpackVertical;
